screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#anomaly-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const severityFilter = container.querySelector("[data-testid='severity-filter']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const typeFilter = container.querySelector("[data-testid='type-filter']");
  const dateFromInput = container.querySelector("[data-testid='date-from']");
  const searchBtn = container.querySelector("[data-testid='search-button']");

  let allRows = [];
  let selectedRowId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    allRows = rows;
    if (rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="5" style="padding: 20px 12px; text-align: center; color: var(--text-muted); font-size: 13px;">異常検出データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const severityColor = r.重要度 === '高' ? '#ff6a6a' : r.重要度 === '中' ? '#ffa500' : '#4a9eff';
      const statusBgColor = r.対応状況 === '未対応' ? 'rgba(255,106,106,0.15)' : r.対応状況 === '対応中' ? 'rgba(255,165,0,0.15)' : r.対応状況 === '解決済み' ? 'rgba(74,158,255,0.15)' : 'rgba(150,150,150,0.15)';
      const statusTextColor = r.重要度 === '高' ? '#ff6a6a' : r.重要度 === '中' ? '#ffa500' : '#4a9eff';

      return `<tr data-id="${r.異常検出ログID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; background: ${selectedRowId === r.異常検出ログID ? 'rgba(74,158,255,0.1)' : 'transparent'}; transition: background 0.2s;" class="anomaly-row">
        <td style="padding: 10px 12px; font-size: 12px; color: ${severityColor}; font-weight: 600;">${r.重要度 || '—'}</td>
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text);">${r.異常タイプ || '—'}</td>
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text);">${r.異常フィールド名 || '—'}</td>
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text-muted);">${r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'}</td>
        <td style="padding: 10px 12px; font-size: 11px; background: ${statusBgColor}; color: ${statusTextColor}; border-radius: 3px; text-align: center; font-weight: 500;">${r.対応状況 || '—'}</td>
      </tr>`;
    }).join("");
  }

  // 詳細パネル描画関数
  function renderDetail(row) {
    selectedRowId = row.異常検出ログID;

    // 再度テーブルを描画してハイライト
    renderRows(allRows);

    const detailHtml = `
      <div>
        <h3 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600; color: var(--text);">異常詳細</h3>

        <div style="display: grid; grid-template-columns: 1fr; gap: 8px; font-size: 12px;">
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">異常検出ログID</div>
            <div style="color: var(--text); font-family: monospace; word-break: break-all;">${row.異常検出ログID || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">営業データID</div>
            <div style="color: var(--text); font-family: monospace; word-break: break-all;">${row.営業データID || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">異常タイプ</div>
            <div style="color: var(--text);">${row.異常タイプ || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">異常フィールド</div>
            <div style="color: var(--text);">${row.異常フィールド名 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">検出値</div>
            <div style="color: var(--text); font-family: monospace; word-break: break-all;">${row.検出値 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">期待値</div>
            <div style="color: var(--text); font-family: monospace; word-break: break-all;">${row.期待値 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">重要度</div>
            <div style="color: var(--text);">${row.重要度 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">対応状況</div>
            <div style="color: var(--text);">${row.対応状況 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">請求処理への影響</div>
            <div style="color: var(--text);">${row.請求処理への影響 ? 'あり' : 'なし'}</div>
          </div>
        </div>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 12px;">
        <h3 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600; color: var(--text);">検証ルール</h3>
        <button data-testid="view-rule-button" class="action-btn secondary" style="width: 100%; padding: 8px 12px; font-size: 12px;">検証ルール確認</button>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 12px;">
        <h3 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600; color: var(--text);">対応コメント</h3>
        <textarea data-testid="comment-input" placeholder="対応内容を入力してください..." style="width: 100%; padding: 8px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px; font-size: 12px; resize: vertical; min-height: 80px; font-family: inherit;">${row.対応コメント || ''}</textarea>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 12px;">
        <h3 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600; color: var(--text);">修正提案</h3>
        <div style="background: rgba(74,158,255,0.08); border-left: 3px solid #4a9eff; padding: 10px; border-radius: 4px; font-size: 12px; color: var(--text); margin-bottom: 12px;">
          ${row.期待値 ? `推奨値: <strong>${row.期待値}</strong>` : '修正提案なし'}
        </div>
        <button data-testid="confirm-fix-button" class="action-btn secondary" style="width: 100%; padding: 8px 12px; font-size: 12px; margin-bottom: 8px;">修正内容確認</button>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 12px; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
        <button data-testid="approve-button" class="action-btn" style="padding: 8px 12px; font-size: 12px;">承認</button>
        <button data-testid="reject-button" class="action-btn secondary" style="padding: 8px 12px; font-size: 12px;">却下</button>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 12px;">
        <button data-testid="edit-data-button" class="action-btn secondary" style="width: 100%; padding: 8px 12px; font-size: 12px;">データ修正</button>
      </div>
    `;

    detailPanel.innerHTML = detailHtml;

    // イベントリスナー登録
    detailPanel.querySelector("[data-testid='view-rule-button']").addEventListener("click", () => {
      alert(`検証ルールID: ${row.検証ルールID}\n\n検証ルール詳細を表示します。`);
    });

    detailPanel.querySelector("[data-testid='confirm-fix-button']").addEventListener("click", () => {
      alert(`修正提案: ${row.期待値}\n\n修正内容を確認しました。`);
    });

    detailPanel.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
      const comment = detailPanel.querySelector("[data-testid='comment-input']").value;
      const updated = await window.aivicApi.update(0, row.異常検出ログID, {
        対応状況: '解決済み',
        対応コメント: comment,
        対応日時: new Date().toISOString()
      });
      if (updated) {
        alert("異常を承認しました。");
        window.aivicApi.list(0).then(renderRows);
        detailPanel.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 13px; padding: 40px 20px;">異常を選択してください</div>';
      }
    });

    detailPanel.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
      const comment = detailPanel.querySelector("[data-testid='comment-input']").value;
      const updated = await window.aivicApi.update(0, row.異常検出ログID, {
        対応状況: '無視',
        対応コメント: comment
      });
      if (updated) {
        alert("異常を却下しました。");
        window.aivicApi.list(0).then(renderRows);
        detailPanel.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 13px; padding: 40px 20px;">異常を選択してください</div>';
      }
    });

    detailPanel.querySelector("[data-testid='edit-data-button']").addEventListener("click", () => {
      window.showScreen("scr-1781940688155");
    });
  }

  // 2. 初期データ読み込み
  if (tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  } else {
    window.aivicApi.list(0).then(rows => {
      if (rows) renderRows(rows);
    });
  }

  // 3. 検索ボタン
  searchBtn.addEventListener("click", () => {
    const severity = severityFilter.value;
    const status = statusFilter.value;
    const type = typeFilter.value;
    const dateFrom = dateFromInput.value;

    let filtered = allRows;
    if (severity) filtered = filtered.filter(r => r.重要度 === severity);
    if (status) filtered = filtered.filter(r => r.対応状況 === status);
    if (type) filtered = filtered.filter(r => r.異常タイプ === type);
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filtered = filtered.filter(r => new Date(r.検出日時) >= fromDate);
    }

    renderRows(filtered);
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const row = e.target.closest(".anomaly-row");
    if (row) {
      const rowId = row.dataset.id;
      const rowData = allRows.find(r => r.異常検出ログID === rowId);
      if (rowData) {
        renderDetail(rowData);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const SALES_DATA_TABLE = 0;

  // フォーム要素の参照
  const form = {
    customerId: container.querySelector('input[name="customerId"]'),
    customerName: container.querySelector('input[name="customerName"]'),
    serviceType: container.querySelector('select[name="serviceType"]'),
    salesPerson: container.querySelector('select[name="salesPerson"]'),
    projectName: container.querySelector('input[name="projectName"]'),
    transactionDate: container.querySelector('input[name="transactionDate"]'),
    quantity: container.querySelector('input[name="quantity"]'),
    unitPrice: container.querySelector('input[name="unitPrice"]'),
    contractStartDate: container.querySelector('input[name="contractStartDate"]'),
    contractEndDate: container.querySelector('input[name="contractEndDate"]'),
    billingTarget: container.querySelector('input[name="billingTarget"]'),
    remarks: container.querySelector('textarea[name="remarks"]')
  };

  const calculatedAmountEl = container.querySelector('#calculated-amount');
  const validationResultEl = container.querySelector('#validation-result');
  const billingJudgmentEl = container.querySelector('#billing-judgment');
  const billingStatusEl = container.querySelector('#billing-status');
  const billingAmountEl = container.querySelector('#billing-amount');
  const anomalyLogEl = container.querySelector('#anomaly-log');
  const recentRecordsTbody = container.querySelector('#recent-records-tbody');

  // 金額自動計算
  function updateCalculatedAmount() {
    const qty = parseInt(form.quantity.value) || 0;
    const price = parseInt(form.unitPrice.value) || 0;
    const total = qty * price;
    calculatedAmountEl.textContent = total.toLocaleString('ja-JP');
    billingAmountEl.textContent = '¥' + total.toLocaleString('ja-JP');
  }

  form.quantity.addEventListener('input', updateCalculatedAmount);
  form.unitPrice.addEventListener('input', updateCalculatedAmount);

  // 検証ルール適用（簡易版）
  function validateData() {
    const errors = [];
    const warnings = [];

    if (!form.customerId.value.trim()) errors.push('顧客IDは必須です');
    if (!form.customerName.value.trim()) errors.push('顧客名は必須です');
    if (!form.serviceType.value) errors.push('サービス種別は必須です');
    if (!form.transactionDate.value) errors.push('売上日付は必須です');
    if (!form.quantity.value) errors.push('数量は必須です');
    if (!form.unitPrice.value) errors.push('単価は必須です');

    const qty = parseInt(form.quantity.value) || 0;
    const price = parseInt(form.unitPrice.value) || 0;
    if (qty < 0) errors.push('数量は0以上である必要があります');
    if (price < 0) errors.push('単価は0以上である必要があります');

    if (form.contractStartDate.value && form.contractEndDate.value) {
      if (new Date(form.contractStartDate.value) > new Date(form.contractEndDate.value)) {
        errors.push('契約開始日は終了日より前である必要があります');
      }
    }

    if (form.transactionDate.value) {
      const txDate = new Date(form.transactionDate.value);
      const today = new Date();
      if (txDate > today) {
        warnings.push('売上日付が未来の日付です');
      }
    }

    // 検証結果表示
    let html = '';
    if (errors.length === 0 && warnings.length === 0) {
      html = '<div style="padding: 8px; background: rgba(76,175,80,0.15); border-radius: 3px; border-left: 3px solid #4caf50; color: #a5d6a7;">✓ すべての検証に合格しました</div>';
    } else {
      if (errors.length > 0) {
        html += '<div style="padding: 8px; background: rgba(244,67,54,0.15); border-radius: 3px; border-left: 3px solid #f44336; color: #ef9a9a; margin-bottom: 6px;">';
        html += '<div style="font-weight: 600; margin-bottom: 4px;">エラー (' + errors.length + '件)</div>';
        errors.forEach(e => html += '<div>• ' + e + '</div>');
        html += '</div>';
      }
      if (warnings.length > 0) {
        html += '<div style="padding: 8px; background: rgba(255,193,7,0.15); border-radius: 3px; border-left: 3px solid #ffc107; color: #ffe082;">';
        html += '<div style="font-weight: 600; margin-bottom: 4px;">警告 (' + warnings.length + '件)</div>';
        warnings.forEach(w => html += '<div>• ' + w + '</div>');
        html += '</div>';
      }
    }
    validationResultEl.innerHTML = html;

    return errors.length === 0;
  }

  // 請求対象判定
  function updateBillingJudgment() {
    const isBillingTarget = form.billingTarget.checked;
    const amount = (parseInt(form.quantity.value) || 0) * (parseInt(form.unitPrice.value) || 0);

    billingStatusEl.textContent = isBillingTarget ? '対象' : '対象外';
    billingStatusEl.style.color = isBillingTarget ? '#a5d6a7' : '#ef9a9a';
  }

  form.billingTarget.addEventListener('change', updateBillingJudgment);

  // 最近の入力履歴を表示
  function renderRecentRecords(records) {
    if (!records || records.length === 0) {
      recentRecordsTbody.innerHTML = '<tr><td colspan="3" style="padding: 12px 4px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }

    const recent = records.slice(0, 5);
    recentRecordsTbody.innerHTML = recent.map(r => {
      const amount = (r.quantity || 0) * (r.unitPrice || 0);
      const status = r.dataQualityStatus || '未検証';
      const statusColor = status === '正常' ? '#a5d6a7' : status === '警告' ? '#ffe082' : '#ef9a9a';
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 4px; color: var(--text);">${r.customerName || '-'}</td>
        <td style="padding: 6px 4px; text-align: right; color: var(--text);">¥${amount.toLocaleString('ja-JP')}</td>
        <td style="padding: 6px 4px; text-align: center; color: ${statusColor}; font-weight: 600; font-size: 10px;">${status}</td>
      </tr>`;
    }).join('');
  }

  // 初期データ表示
  if (tables[SALES_DATA_TABLE] && tables[SALES_DATA_TABLE].records) {
    renderRecentRecords(tables[SALES_DATA_TABLE].records);
  }

  // 保存ボタン
  container.querySelector('[data-testid="save-button"]').addEventListener('click', async () => {
    if (!validateData()) {
      alert('入力内容に誤りがあります。修正してください。');
      return;
    }

    const qty = parseInt(form.quantity.value) || 0;
    const price = parseInt(form.unitPrice.value) || 0;

    const newRecord = {
      customerId: form.customerId.value.trim(),
      customerName: form.customerName.value.trim(),
      serviceType: form.serviceType.value,
      salesPerson: form.salesPerson.value,
      projectName: form.projectName.value.trim(),
      transactionDate: form.transactionDate.value,
      quantity: qty,
      unitPrice: price,
      transactionAmount: qty * price,
      contractStartDate: form.contractStartDate.value,
      contractEndDate: form.contractEndDate.value,
      billingTarget: form.billingTarget.checked,
      remarks: form.remarks.value.trim(),
      dataQualityStatus: '正常',
      createdAt: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(SALES_DATA_TABLE, newRecord);
    if (saved) {
      alert('営業データを保存しました。');
      // フォームクリア
      Object.values(form).forEach(el => {
        if (el.type === 'checkbox') el.checked = false;
        else el.value = '';
      });
      calculatedAmountEl.textContent = '0';
      billingAmountEl.textContent = '¥0';
      billingStatusEl.textContent = '未設定';
      billingStatusEl.style.color = 'var(--text)';
      validationResultEl.innerHTML = '<div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; border-left: 3px solid rgba(255,255,255,0.2);">入力データを確認してください</div>';

      // 最近の入力を更新
      const updated = await window.aivicApi.list(SALES_DATA_TABLE);
      if (updated) renderRecentRecords(updated);
    }
  });

  // クリアボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    Object.values(form).forEach(el => {
      if (el.type === 'checkbox') el.checked = false;
      else el.value = '';
    });
    calculatedAmountEl.textContent = '0';
    billingAmountEl.textContent = '¥0';
    billingStatusEl.textContent = '未設定';
    billingStatusEl.style.color = 'var(--text)';
    validationResultEl.innerHTML = '<div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; border-left: 3px solid rgba(255,255,255,0.2);">入力データを確認してください</div>';
  });

  // リアルタイム検証
  Object.values(form).forEach(el => {
    el.addEventListener('change', validateData);
    el.addEventListener('input', validateData);
  });

  // 初期検証
  validateData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const SALES_DATA_IDX = 0;           // 営業データ
  const VALIDATION_RULES_IDX = 1;     // 営業データ検証ルール
  const ANOMALY_LOG_IDX = 2;          // 営業データ異常検出ログ
  const BILLING_ITEMS_IDX = 3;        // 請求対象項目定義
  const CUSTOMER_BILLING_IDX = 4;     // 顧客請求集計
  const SERVICE_BILLING_IDX = 5;      // サービス請求集計
  const METADATA_IDX = 6;             // 営業データメタデータ
  const MONTHLY_SUMMARY_IDX = 7;      // 月次サマリーテンプレート
  const VALIDATION_RESULT_IDX = 8;    // データ品質検証結果
  const MISSING_DATA_IDX = 9;         // 不足データ通知ログ

  let currentFilteredData = [];
  let currentDiscountConfig = { type: '', value: 0, reason: '' };
  let baseAmount = 0;
  let baseTax = 0;
  let baseCount = 0;

  // ========== 1. 再描画・計算関数 ==========

  function formatCurrency(amount) {
    return '¥' + Math.floor(amount).toLocaleString('ja-JP');
  }

  function calculateTax(amount) {
    return Math.floor(amount * 0.1);
  }

  async function loadDiscountRules() {
    const rules = tables[BILLING_ITEMS_IDX]?.records || [];
    const rulesHtml = rules
      .filter(r => r.請求計算方法 && r.請求計算方法.includes('割引'))
      .slice(0, 5)
      .map(r => `
        <div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; font-size: 10px; color: var(--text-muted);">
          <div style="font-weight: 600; color: var(--text);">${r.項目名 || 'ルール'}</div>
          <div>${r.説明 || '割引ルール'}</div>
        </div>
      `).join('');

    container.querySelector('#discount-rules-list').innerHTML = rulesHtml || '<div style="padding: 8px; font-size: 11px; color: var(--text-muted); text-align: center;">割引ルールなし</div>';
  }

  async function loadAnomalyLogs() {
    const logs = tables[ANOMALY_LOG_IDX]?.records || [];
    const relevantLogs = logs.filter(l => l.請求処理への影響 === true).slice(0, 4);

    if (relevantLogs.length === 0) {
      container.querySelector('#anomaly-log-list').innerHTML = '<div style="padding: 8px; font-size: 11px; color: var(--text-muted); text-align: center;">異常なし</div>';
      return;
    }

    const logsHtml = relevantLogs.map(l => `
      <div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.08); font-size: 9px;">
        <div style="color: ${l.重要度 === '高' ? '#ef4444' : l.重要度 === '中' ? '#f59e0b' : '#3b82f6'}; font-weight: 600;">
          [${l.重要度}] ${l.異常タイプ}
        </div>
        <div style="color: var(--text-muted); margin-top: 2px;">${l.異常フィールド名}: ${l.検出値}</div>
      </div>
    `).join('');

    container.querySelector('#anomaly-log-list').innerHTML = logsHtml;
  }

  async function loadMissingDataAlerts() {
    const missing = tables[MISSING_DATA_IDX]?.records || [];
    const criticalMissing = missing.filter(m => m.請求影響フラグ === true && m.通知ステータス === '未対応').slice(0, 3);

    if (criticalMissing.length === 0) {
      container.querySelector('#missing-data-alert').style.display = 'none';
      return;
    }

    container.querySelector('#missing-data-alert').style.display = 'block';
    const details = criticalMissing.map(m => `<div>• ${m.不足項目名} (${m.重要度レベル})</div>`).join('');
    container.querySelector('#missing-data-details').innerHTML = details;
  }

  function updateQualityScore(passCount, totalCount) {
    const score = totalCount > 0 ? Math.round((passCount / totalCount) * 100) : 0;
    container.querySelector('[data-testid="quality-score"]').textContent = `${score}/100`;
    container.querySelector('#quality-score-bar').style.width = score + '%';
  }

  function updateValidationCounts() {
    const validationResults = tables[VALIDATION_RESULT_IDX]?.records || [];
    const passCount = validationResults.filter(r => r.検証ステータス === '合格').length;
    const failCount = validationResults.filter(r => r.検証ステータス === '不合格').length;

    container.querySelector('[data-testid="validation-pass"]').textContent = passCount;
    container.querySelector('[data-testid="validation-fail"]').textContent = failCount;
    updateQualityScore(passCount, passCount + failCount);
  }

  function updateAmountDisplay() {
    const beforeTotal = baseAmount + baseTax;
    let afterAmount = baseAmount;
    let afterTax = baseTax;
    let discountAmount = 0;

    if (currentDiscountConfig.type === 'RATE') {
      discountAmount = Math.floor(baseAmount * (currentDiscountConfig.value / 100));
      afterAmount = baseAmount - discountAmount;
      afterTax = calculateTax(afterAmount);
    } else if (currentDiscountConfig.type === 'FIXED') {
      discountAmount = Math.min(currentDiscountConfig.value, baseAmount);
      afterAmount = baseAmount - discountAmount;
      afterTax = calculateTax(afterAmount);
    }

    const afterTotal = afterAmount + afterTax;
    const discountRate = baseAmount > 0 ? ((discountAmount / baseAmount) * 100).toFixed(1) : 0;

    container.querySelector('[data-testid="before-total"]').textContent = formatCurrency(beforeTotal);
    container.querySelector('[data-testid="before-amount"]').textContent = formatCurrency(baseAmount);
    container.querySelector('[data-testid="before-tax"]').textContent = formatCurrency(baseTax);

    container.querySelector('[data-testid="after-total"]').textContent = formatCurrency(afterTotal);
    container.querySelector('[data-testid="after-amount"]').textContent = formatCurrency(afterAmount);
    container.querySelector('[data-testid="after-tax"]').textContent = formatCurrency(afterTax);
    container.querySelector('[data-testid="discount-amount"]').textContent = formatCurrency(discountAmount);
    container.querySelector('[data-testid="discount-rate"]').textContent = discountRate + '%';
  }

  // ========== 2. 初期データ読み込み ==========

  async function initializeScreen() {
    await loadDiscountRules();
    await loadAnomalyLogs();
    await loadMissingDataAlerts();
    updateValidationCounts();
    updateAmountDisplay();
  }

  // ========== 3. フィルター適用 ==========

  container.querySelector('[data-testid="filter-apply-btn"]').addEventListener('click', async () => {
    const month = container.querySelector('[data-testid="billing-month"]').value;
    const customerId = container.querySelector('[data-testid="customer-filter"]').value;
    const serviceType = container.querySelector('[data-testid="service-type-filter"]').value;

    const salesData = tables[SALES_DATA_IDX]?.records || [];
    currentFilteredData = salesData.filter(s => {
      const matches = (s.請求対象フラグ === true || s.請求対象フラグ === 'true');
      const customerMatch = !customerId || s.顧客ID === customerId;
      const serviceMatch = !serviceType || s.商品ID?.includes(serviceType);
      return matches && customerMatch && serviceMatch;
    });

    baseAmount = currentFilteredData.reduce((sum, s) => sum + (s.取引金額 || 0), 0);
    baseTax = calculateTax(baseAmount);
    baseCount = currentFilteredData.length;

    container.querySelector('[data-testid="base-amount"]').textContent = formatCurrency(baseAmount);
    container.querySelector('[data-testid="base-tax"]').textContent = formatCurrency(baseTax);
    container.querySelector('[data-testid="base-count"]').textContent = baseCount;

    currentDiscountConfig = { type: '', value: 0, reason: '' };
    container.querySelector('[data-testid="discount-type"]').value = '';
    container.querySelector('[data-testid="discount-value"]').value = '';
    container.querySelector('[data-testid="discount-reason"]').value = '';

    updateAmountDisplay();
  });

  // ========== 4. 割引適用 ==========

  container.querySelector('[data-testid="apply-discount-btn"]').addEventListener('click', () => {
    const type = container.querySelector('[data-testid="discount-type"]').value;
    const value = parseFloat(container.querySelector('[data-testid="discount-value"]').value) || 0;
    const reason = container.querySelector('[data-testid="discount-reason"]').value;

    if (!type || value <= 0) {
      alert('割引種別と割引値を入力してください');
      return;
    }

    currentDiscountConfig = { type, value, reason };
    updateAmountDisplay();
  });

  // ========== 5. 請求確定 ==========

  container.querySelector('[data-testid="confirm-billing-btn"]').addEventListener('click', async () => {
    if (baseAmount === 0) {
      alert('請求対象データがありません');
      return;
    }

    const afterAmount = currentDiscountConfig.type === 'RATE'
      ? baseAmount - Math.floor(baseAmount * (currentDiscountConfig.value / 100))
      : currentDiscountConfig.type === 'FIXED'
      ? baseAmount - Math.min(currentDiscountConfig.value, baseAmount)
      : baseAmount;

    const afterTax = calculateTax(afterAmount);

    const billingRecord = {
      顧客ID: container.querySelector('[data-testid="customer-filter"]').value || 'ALL',
      請求年月: container.querySelector('[data-testid="billing-month"]').value || new Date().toISOString().slice(0, 7),
      請求金額: afterAmount,
      税額: afterTax,
      請求金額合計: afterAmount + afterTax,
      対象営業データ件数: baseCount,
      検証ステータス: '検証済み',
      異常フラグ: false,
      請求ステータス: '未処理',
      摘要: currentDiscountConfig.reason || '割引適用済み'
    };

    const saved = await window.aivicApi.save(CUSTOMER_BILLING_IDX, billingRecord);
    if (saved) {
      alert('請求が確定されました');
      window.showScreen('scr-1781940712852');
    }
  });

  // ========== 6. ナビゲーション ==========

  container.querySelector('[data-testid="back-to-data-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781940688155');
  });

  container.querySelector('[data-testid="go-to-summary-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781940712852');
  });

  container.querySelector('[data-testid="preview-invoice-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781940940693');
  });

  // ========== 7. 初期化実行 ==========

  initializeScreen();
}
